import Seo from "../components/Seo"
import Image from "next/image"
import { useState } from "react"

export default function Home() {
  const [status, setStatus] = useState<'idle'|'sending'|'ok'|'error'>('idle')

  return (
    <>
      <Seo />
      <main style={{ maxWidth: 1100, margin: '0 auto', padding: 24 }}>
        
        <section style={{ textAlign: 'center', padding: '48px 0' }}>
          <h1 style={{ fontSize: 28, marginBottom: 8 }}>
            Khadeeja Designs — Handcrafted Aari Embroidery
          </h1>
          <p style={{ maxWidth: 720, margin: '0 auto' }}>
            Bespoke, handcrafted aari embroidery for bridal and couture — transforming sketches into heirloom-ready garments.
          </p>
        </section>

        <section style={{ marginTop: 32 }}>
          <h2 style={{ fontSize: 20 }}>Selected Work</h2>
          <div style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))',
            gap: 12,
            marginTop: 12
          }}>
            
            <div style={{ border: '1px solid #e5e7eb', borderRadius: 8, overflow: 'hidden' }}>
              <div style={{ position: 'relative', width: '100%', paddingTop: '75%' }}>
                <Image src="/images/placeholder-1.svg" alt="Bridal Aari Blouse" fill style={{ objectFit: 'cover' }} />
              </div>
              <div style={{ padding: 12 }}>
                <strong>Bridal Aari Blouse</strong>
              </div>
            </div>

            <div style={{ border: '1px solid #e5e7eb', borderRadius: 8, overflow: 'hidden' }}>
              <div style={{ position: 'relative', width: '100%', paddingTop: '75%' }}>
                <Image src="/images/placeholder-2.svg" alt="Custom Blouse" fill style={{ objectFit: 'cover' }} />
              </div>
              <div style={{ padding: 12 }}>
                <strong>Custom Blouse</strong>
              </div>
            </div>

          </div>
        </section>

        <section id="contact" style={{ marginTop: 40 }}>
          <h2>Contact</h2>

          <form
            onSubmit={async (e) => {
              e.preventDefault()
              setStatus('sending')
              const data = new FormData(e.currentTarget)
              
              const res = await fetch('/api/contact', {
                method: 'POST',
                body: data,
              })

              setStatus(res.ok ? 'ok' : 'error')
              if (res.ok) e.currentTarget.reset()
            }}
            style={{ maxWidth: 560 }}
          >
            <input name="name" placeholder="Name" required style={{ width: '100%', padding: 8, marginBottom: 8 }} />
            <input name="email" placeholder="Email" type="email" required style={{ width: '100%', padding: 8, marginBottom: 8 }} />
            <textarea name="message" placeholder="Message" required style={{ width: '100%', padding: 8, marginBottom: 8, minHeight: 120 }} />

            <input name="_gotcha" style={{ display: 'none' }} />

            <button type="submit" style={{ padding: '10px 18px', background: '#111827', color: '#fff', borderRadius: 6 }}>
              {status === 'sending' ? 'Sending...' : 'Send Message'}
            </button>

            {status === 'ok'    && <div style={{ marginTop: 12 }}>Message sent!</div>}
            {status === 'error' && <div style={{ marginTop: 12 }}>Something went wrong.</div>}
          </form>
        </section>

      </main>
    </>
  )
}
